#include <stdio.h>

/* teste do desafio enderecos-na-tela — counter_protocol (03-tdd 3.9.3).
   O main e o relatorio sao do harness; aqui so existem cenarios SM_TEST.
   Cada cenario escreve num arquivo o que a pessoa "digitaria", aponta o
   stdin para esse arquivo (freopen) e captura o stdout no proprio teste.
   Os arquivos temporarios sao POR CENARIO: um cenario nunca le a entrada
   nem a captura do outro. Nunca ha fclose de stdin/stdout — so fflush —
   para o segundo freopen ficar legal (C11 7.21.4).
   O ENDERECO em si nao e asseverado em lugar nenhum: ele muda a cada
   execucao. O que o teste confere e o TAMANHO dele, que e fixo. */

/* prototipo da funcao do aluno (o teste declara o que exercita) */
void enderecosNaTela(void);

SM_TEST(trinta_e_mil_novecentos_e_noventa_e_cinco) {
    FILE *e = fopen("sm_entrada_1.tmp", "w");
    fprintf(e, "30\n1995\n");
    fclose(e);
    freopen("sm_entrada_1.tmp", "r", stdin);

    freopen("sm_saida_1.tmp", "w", stdout);
    enderecosNaTela();
    fflush(stdout);

    FILE *f = fopen("sm_saida_1.tmp", "r");
    char linha[80] = "(nada impresso)";
    fgets(linha, 80, f);
    checa_str("o valor de idade", linha, "idade vale 30\n",
              "o 30 digitado entrou em idade pela scanf com o &");
    fgets(linha, 80, f);
    checa_str("o tamanho do endereco de idade", linha,
              "o endereco de idade ocupa 8 bytes\n",
              "sizeof(&idade) mede o endereco, nao a caixa: 8 bytes nesta maquina");
    fgets(linha, 80, f);
    checa_str("o valor de ano", linha, "ano vale 1995\n",
              "a segunda scanf leu o 1995 para dentro de ano");
    fgets(linha, 80, f);
    checa_str("o tamanho do endereco de ano", linha,
              "o endereco de ano ocupa 8 bytes\n",
              "todo endereco ocupa o mesmo: o segundo tambem da 8 bytes");
    char fim[80] = "(nada impresso)";
    fgets(fim, 80, f);
    checa_str("nao ha linha a mais", fim, "(nada impresso)",
              "a saida acaba na quarta linha: nenhuma pergunta e nenhuma linha extra");
    fclose(f);
}

SM_TEST(outros_dois_numeros_digitados) {
    FILE *e = fopen("sm_entrada_2.tmp", "w");
    fprintf(e, "7\n2026\n");
    fclose(e);
    freopen("sm_entrada_2.tmp", "r", stdin);

    freopen("sm_saida_2.tmp", "w", stdout);
    enderecosNaTela();
    fflush(stdout);

    FILE *f = fopen("sm_saida_2.tmp", "r");
    char linha[80] = "(nada impresso)";
    fgets(linha, 80, f);
    checa_str("o valor de idade com outro numero", linha, "idade vale 7\n",
              "quem le de verdade responde 7 quando o 7 e digitado");
    fgets(linha, 80, f);
    checa_str("o tamanho do endereco nao mudou", linha,
              "o endereco de idade ocupa 8 bytes\n",
              "o valor mudou e o tamanho do endereco nao: ele nao depende do conteudo");
    fgets(linha, 80, f);
    checa_str("o valor de ano com outro numero", linha, "ano vale 2026\n",
              "a segunda leitura tambem acompanha o que foi digitado");
    fclose(f);
}

