#include <stdio.h>

void enderecosNaTela(void) {
    int idade = 0;
    int ano = 0;

    scanf("%d", &idade);
    scanf("%d", &ano);

    int papelIdade = sizeof(&idade);
    int papelAno = sizeof(&ano);

    printf("idade vale %d\n", idade);
    printf("o endereco de idade ocupa %d bytes\n", papelIdade);
    printf("ano vale %d\n", ano);
    printf("o endereco de ano ocupa %d bytes\n", papelAno);
}
